# ═══════════════════════════════════════════════════════════════════════

stage "Firebase: crear el proyecto"
say "Vamos a crear el proyecto de Firebase que va a servir Authentication y"
say "Firestore para CLACK."
open_url "https://console.firebase.google.com/"
step "Click en 'Agregar proyecto' / 'Add project'."
step "Nombre sugerido: clack (o el que prefieras)."
step "Si te pregunta por Google Analytics, podes desactivarlo: no lo usamos."
step "Click en 'Crear proyecto' y esperá a que termine."
say ""
say "Una vez creado, el ID del proyecto aparece en la URL de la consola"
say "(algo como clack-a1b2c) y tambien en el engranaje > Configuracion del"
say "proyecto > General, campo 'ID de proyecto'."
ask FIREBASE_PROJECT_ID "ID del proyecto de Firebase:"
write_env VITE_FIREBASE_PROJECT_ID "$FIREBASE_PROJECT_ID"
write_env FIREBASE_ADMIN_PROJECT_ID "$FIREBASE_PROJECT_ID"
note "el ID de proyecto es el mismo valor para VITE_FIREBASE_PROJECT_ID y"
note "para FIREBASE_ADMIN_PROJECT_ID: ya quedaron los dos escritos."

stage "Firebase: Authentication (Email/Password + Google)"
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/authentication/providers"
step "Si es la primera vez, click en 'Comenzar' / 'Get started'."
step "En la lista de proveedores, abri 'Correo electronico/contraseña',"
step "activa el interruptor y Guardar."
step "Abri 'Google' y activalo. Se abre un paso 2 de 2 con dos campos:"
step "'Nombre publico del proyecto': viene autocompletado con algo como"
step "'project-123456789', que es el numero interno del proyecto. Cambialo"
step "a CLACK: es lo que un usuario ve en la pantalla de Google al iniciar"
step "sesion ('Continuar a CLACK'), y dejarlo con el numero se ve roto."
step "'Correo electronico de asistencia del proyecto': el desplegable te"
step "muestra tu propia cuenta de Google: dejala como esta."
step "Las secciones colapsables de abajo (entidades seguras, SDK web) son"
step "para casos avanzados: no hace falta abrirlas."
step "Guardar."
say ""
warn "no hace falta ninguna otra configuracion aca: la app va a usar estos"
warn "dos metodos y ninguno mas."
confirm "Los dos proveedores quedaron activados?" || warn "segui cuando esten listos, podes volver a correr el wizard"

stage "Firebase: Firestore (modo produccion)"
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/firestore"
step "Click en 'Crear base de datos' / 'Create database'."
step "Elegi modo PRODUCCION (Production mode), NO modo de prueba."
note "modo produccion arranca con todo cerrado por defecto, que es"
note "exactamente lo que el proyecto necesita: las security rules se"
note "escriben en el andamiaje, nunca queda todo abierto ni un dia."
step "Elegi la ubicacion. Sugerido para Argentina: southamerica-east1"
step "(Sao Paulo). Confirmá: la ubicación NO se puede cambiar despues."
step "Click en 'Habilitar' / 'Enable' y esperá a que termine."
confirm "Firestore quedo creado en modo produccion?" || warn "segui cuando este listo"

stage "Firebase: configuracion de la app web"
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/settings/general"
step "Baja hasta 'Tus apps' / 'Your apps'."
step "Si no hay ninguna app web, click en el icono </> para agregar una."
step "Nombre sugerido: clack-web. NO marques 'Tambien configura Firebase"
step "Hosting': el deploy va por Vercel, no por Firebase Hosting."
step "Copia los valores del objeto firebaseConfig que te muestra:"
say "    apiKey, authDomain, appId"
ask FIREBASE_API_KEY "apiKey:"
ask FIREBASE_AUTH_DOMAIN "authDomain (ej: clack-xxxxx.firebaseapp.com):"
ask FIREBASE_APP_ID "appId:"
write_env VITE_FIREBASE_API_KEY "$FIREBASE_API_KEY"
write_env VITE_FIREBASE_AUTH_DOMAIN "$FIREBASE_AUTH_DOMAIN"
write_env VITE_FIREBASE_APP_ID "$FIREBASE_APP_ID"
write_env VITE_USE_FIREBASE_EMULATORS "true"
note "VITE_USE_FIREBASE_EMULATORS quedo en true: en tu maquina local el"
note "cliente habla con el Emulator Suite, no con el proyecto real."

stage "Firebase: clave del Admin SDK"
say "Esta clave es la que usan las Vercel Functions para verificar tokens"
say "y asignar el rol de admin. Es un secreto real: nunca va al repositorio."
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/settings/serviceaccounts/adminsdk"
step "Click en 'Generar nueva clave privada' / 'Generate new private key'."
step "Confirma. Se descarga un archivo .json a tu carpeta de Descargas."
warn "ese archivo .json es una credencial completa. No lo copies dentro de"
warn "la carpeta del proyecto, y borralo de Descargas apenas termines aca."
say ""
step "Abri el .json descargado con un editor de texto."
step "Copia el valor del campo \"client_email\" (sin las comillas)."
ask FIREBASE_ADMIN_CLIENT_EMAIL "client_email:"
say ""
step "Copia el valor del campo \"private_key\" COMPLETO, tal cual aparece"
step "en el archivo: con las comillas afuera pero sin sacarlas, y con los"
step "\\n literales adentro (NO son saltos de linea reales en el archivo"
step "de texto: son la secuencia de dos caracteres barra-ene)."
note "el codigo hace .replace(/\\\\n/g, '\\n') al inicializar, asi que espera"
note "exactamente ese formato. Pegar la clave ya con saltos de linea reales"
note "es el error mas comun de este paso y el mensaje que da no ayuda nada."
ask_secret FIREBASE_ADMIN_PRIVATE_KEY "private_key completo (una sola linea, con los \\n literales):"
write_env FIREBASE_ADMIN_CLIENT_EMAIL "$FIREBASE_ADMIN_CLIENT_EMAIL"
write_env FIREBASE_ADMIN_PRIVATE_KEY "$FIREBASE_ADMIN_PRIVATE_KEY"
say ""
warn "borra ahora el .json descargado de tu carpeta de Descargas: ya"
warn "copiaste los dos campos que hacen falta."
confirm "Borraste el archivo .json descargado?" || warn "borralo antes de seguir"

