stage "Vercel: crear y linkear el proyecto"
say "Vamos a crear el proyecto con el CLI en vez del dashboard, para no"
say "disparar un deploy automatico todavia: no hay package.json, asi que"
say "cualquier deploy ahora fallaria sin que eso signifique nada malo."
say ""
if ! command -v vercel >/dev/null 2>&1; then
  warn "no se encontro el comando 'vercel'. Instalalo con: npm i -g vercel"
  SKIPPED+=("vercel CLI no instalado: correr este stage a mano despues")
else
  if ! vercel whoami >/dev/null 2>&1; then
    step "No hay sesion de Vercel CLI activa. Se va a abrir el login."
    pause "Presiona Enter para correr 'vercel login'..."
    vercel login || warn "el login no se completo; volve a correr el wizard"
  fi
  step "Ahora corre 'vercel link'. Te va a preguntar equipo/scope y si"
  step "queres crear un proyecto nuevo: decile que si, nombre 'clack'."
  pause "Presiona Enter para correr 'vercel link'..."
  vercel link || warn "el link no se completo; volve a correr este stage"
fi

stage "Vercel: cargar las variables de entorno"
say "Con el proyecto ya linkeado, subimos todo lo que juntamos hasta"
say "ahora a Production Y Preview. Firestore/AWS reales se comparten"
say "entre los dos, no hay un proyecto de staging aparte."
say ""
note "VITE_USE_FIREBASE_EMULATORS NO se sube: en Vercel esa variable no"
note "existe, y sin ella el cliente habla con el proyecto real de Firebase."
vercel_env "VITE_FIREBASE_API_KEY" "$FIREBASE_API_KEY"
vercel_env "VITE_FIREBASE_AUTH_DOMAIN" "$FIREBASE_AUTH_DOMAIN"
vercel_env "VITE_FIREBASE_PROJECT_ID" "$FIREBASE_PROJECT_ID"
vercel_env "VITE_FIREBASE_APP_ID" "$FIREBASE_APP_ID"
vercel_env "FIREBASE_ADMIN_PROJECT_ID" "$FIREBASE_PROJECT_ID"
vercel_env "FIREBASE_ADMIN_CLIENT_EMAIL" "$FIREBASE_ADMIN_CLIENT_EMAIL"
vercel_env "FIREBASE_ADMIN_PRIVATE_KEY" "$FIREBASE_ADMIN_PRIVATE_KEY"
vercel_env "S3_REGION" "$S3_REGION"
vercel_env "S3_BUCKET" "$S3_BUCKET"
vercel_env "S3_ACCESS_KEY_ID" "$S3_ACCESS_KEY_ID"
vercel_env "S3_SECRET_ACCESS_KEY" "$S3_SECRET_ACCESS_KEY"
say ""
note "si alguna salio en amarillo arriba (ya existia de una corrida"
note "anterior), anda al dashboard y confirma el valor a mano:"
note "Project Settings > Environment Variables."

stage "Vercel: conectar el repositorio de GitHub"
say "Ultimo paso: conectar el proyecto a GitHub para que cada push dispare"
say "un preview y cada merge a main despliegue a produccion."
